script:
# =========================
# MISSION INTERVENTION BEFORE SUBMIT
# Validation only
# Do not create logs, Stock Entries or update Installed Equipment here.
# All write/update logic must remain in After Submit.
# =========================


# =========================
# GENERAL COMPLETION VALIDATION
# =========================

if not doc.get("custom_start_time"):
    frappe.throw("Please Check In before submitting.")

if (
    doc.get("custom_work_outcome") == "Work Completed"
    and not doc.get("custom_completed_time")
):
    frappe.throw("Please Complete Work before submitting.")

if not doc.get("custom_work_outcome"):
    frappe.throw("Work Outcome is required.")

if not doc.get("custom_work_progress"):
    frappe.throw("Technical Progress Notes are required.")

if not doc.get("custom_client_signature_received"):
    frappe.throw("Please mark Client Signed before submitting.")

if not doc.get("custom_client_signed_time"):
    frappe.throw("Client Signed Time is required.")

if not doc.get("custom_end_time"):
    frappe.throw("Please Check Out before submitting.")


# =========================
# SHARED SWAP VALUES
# =========================

intervention_type = doc.get("custom_intervention_type")
replacement_source = doc.get("custom_replacement_source")
removed_asset_outcome = doc.get("custom_removed_asset_outcome")

component_replacement = (
    str(doc.get("custom_component_replaced") or "0") == "1"
)

component_installation = (
    str(doc.get("custom_component_installation") or "0") == "1"
)

if component_replacement and component_installation:
    frappe.throw(
        "Component Replaced and Component Installation Only "
        "cannot both be selected."
    )


# =========================
# REPLACEMENT SOURCE VALIDATION
# =========================

if (
    intervention_type == "Swap"
    or component_replacement
    or component_installation
):

    if (
        replacement_source == "Another Site"
        and not doc.get("custom_replacement_source_branch")
    ):
        frappe.throw(
            "Replacement Source Branch is required when the replacement "
            "comes from another site."
        )

    if (
        replacement_source == "Stock"
        and not doc.get("custom_replacement_warehouse")
    ):
        frappe.throw(
            "Replacement Source Warehouse is required when the replacement "
            "comes from stock."
        )

    if (
        replacement_source == "Workshop"
        and not doc.get("custom_company_workshop")
    ):
        frappe.throw(
            "Company Workshop is required when the replacement "
            "comes from a workshop."
        )



# =========================
# COMPONENT INSTALLATION ONLY VALIDATION
# Installs an incoming component into an empty position.
# No outgoing component or removed-component outcome is required.
# =========================

if component_installation:

    if not doc.get("custom_asset"):
        frappe.throw(
            "Parent Equipment is required for component installation."
        )

    if not doc.get("custom_new_equipment_component"):
        frappe.throw(
            "New Equipment Component is required for component installation."
        )

    if not doc.get("custom_component_replacement_reason"):
        frappe.throw(
            "Component Installation Reason is required."
        )

    if not replacement_source:
        frappe.throw("Replacement Source is required.")

    if (
        replacement_source == "Another Site"
        and not doc.get("custom_replacement_source_branch")
    ):
        frappe.throw(
            "Replacement Source Branch is required when the component "
            "comes from another site."
        )

    if (
        replacement_source == "Stock"
        and not doc.get("custom_replacement_warehouse")
    ):
        frappe.throw(
            "Replacement Source Warehouse is required when the component "
            "comes from stock."
        )

    if (
        replacement_source == "Workshop"
        and not doc.get("custom_company_workshop")
    ):
        frappe.throw(
            "Company Workshop is required when the component "
            "comes from a workshop."
        )

    incoming_component_values = frappe.db.get_value(
        "Equipment Component",
        doc.get("custom_new_equipment_component"),
        [
            "custom_status",
            "custom_parent_equipment",
            "custom_customer",
            "custom_branch"
        ],
        as_dict=True
    )

    if not incoming_component_values:
        frappe.throw(
            "Incoming Equipment Component was not found: "
            + str(doc.get("custom_new_equipment_component"))
        )

    if (
        incoming_component_values.get("custom_parent_equipment")
        == doc.get("custom_asset")
    ):
        frappe.throw(
            "The selected component is already installed on this equipment."
        )

    if replacement_source in [
        "Stock",
        "Workshop",
        "Customer Supplied",
        "New Component"
    ] and incoming_component_values.get("custom_parent_equipment"):
        frappe.throw(
            "The selected component is already installed on "
            + str(
                incoming_component_values.get(
                    "custom_parent_equipment"
                )
            )
            + "."
        )

# =========================
# COMPONENT REPLACEMENT VALIDATION
# Uses permanent Equipment Component IDs.
# =========================

if component_replacement:

    if intervention_type != "Swap":
        frappe.throw(
            "Component Replaced can only be used with Intervention Type Swap."
        )

    if not doc.get("custom_asset"):
        frappe.throw(
            "Parent Equipment is required for component replacement."
        )

    if not doc.get("custom_equipment_component"):
        frappe.throw(
            "Outgoing Equipment Component is required."
        )

    if not doc.get("custom_new_equipment_component"):
        frappe.throw(
            "New Equipment Component is required."
        )

    if (
        doc.get("custom_equipment_component")
        == doc.get("custom_new_equipment_component")
    ):
        frappe.throw(
            "Outgoing and incoming Equipment Components cannot be the same."
        )

    if not doc.get("custom_component_replacement_reason"):
        frappe.throw(
            "Component Replacement Reason is required."
        )

    if not replacement_source:
        frappe.throw("Replacement Source is required.")

    if not removed_asset_outcome:
        frappe.throw("Removed Component Outcome is required.")

    if (
        removed_asset_outcome == "Workshop for Repair"
        and not doc.get("custom_company_workshop")
    ):
        frappe.throw(
            "Company Workshop is required when the removed component "
            "is sent for repair."
        )


# =========================
# STOCK COMPONENT VALIDATION
# Applies only when an incoming component comes from stock.
# =========================

if (
    (component_replacement or component_installation)
    and replacement_source == "Stock"
):

    source_warehouse = doc.get(
        "custom_replacement_warehouse"
    )

    incoming_component = doc.get(
        "custom_new_equipment_component"
    )

    if not source_warehouse:
        frappe.throw(
            "Replacement Source Warehouse is required."
        )

    if not incoming_component:
        frappe.throw(
            "Please select the incoming stock component "
            "before submitting."
        )

    matching_rows = []

    for row in doc.get("custom_parts_table") or []:

        is_component_row = (
            str(
                row.get(
                    "custom_is_component_replacement"
                ) or "0"
            ) == "1"
        )

        if (
            is_component_row
            and row.get("custom_equipment_component")
            == incoming_component
        ):
            matching_rows.append(row)

    if len(matching_rows) == 0:
        frappe.throw(
            "No matching component row was found "
            "in the Parts Used table."
        )

    if len(matching_rows) > 1:
        frappe.throw(
            "More than one component row exists for incoming "
            "Equipment Component "
            + str(incoming_component)
            + "."
        )

    stock_row = matching_rows[0]

    item_code = stock_row.get("custom_item_code")
    serial_no = stock_row.get("custom_serial_no")
    row_warehouse = stock_row.get("custom_warehouse")
    quantity = stock_row.get("custom_qty") or 0

    if not item_code:
        frappe.throw(
            "Item Code is missing from the component row."
        )

    if not serial_no:
        frappe.throw(
            "Serial No is missing from the component row."
        )

    if not row_warehouse:
        frappe.throw(
            "Warehouse is missing from the component row."
        )

    if row_warehouse != source_warehouse:
        frappe.throw(
            "The warehouse in the component row does not match "
            "Replacement Source Warehouse."
        )

    if float(quantity) != 1:
        frappe.throw(
            "A serialized component must have Qty = 1."
        )


    if str(
        stock_row.get("custom_stock_issued") or "0"
    ) == "1":
        frappe.throw(
            "The selected component has already been marked "
            "as issued from stock."
        )

    if stock_row.get("custom_stock_entry"):
        frappe.throw(
            "A Stock Entry is already linked to the selected component row."
        )


    # =========================
    # VALIDATE EQUIPMENT COMPONENT
    # =========================

    component_values = frappe.db.get_value(
        "Equipment Component",
        incoming_component,
        [
            "custom_item",
            "custom_serial_number",
            "custom_status",
            "custom_parent_equipment"
        ],
        as_dict=True
    )

    if not component_values:
        frappe.throw(
            "Incoming Equipment Component was not found: "
            + str(incoming_component)
        )

    if component_values.get("custom_item") != item_code:
        frappe.throw(
            "The Item on Equipment Component "
            + str(incoming_component)
            + " does not match the Item in the Parts Used row."
        )

    if (
        component_values.get("custom_serial_number")
        != serial_no
    ):
        frappe.throw(
            "The Serial No on Equipment Component "
            + str(incoming_component)
            + " does not match the Serial No in the Parts Used row."
        )

    if component_values.get("custom_parent_equipment"):
        frappe.throw(
            "Incoming Equipment Component "
            + str(incoming_component)
            + " is already installed on "
            + str(
                component_values.get(
                    "custom_parent_equipment"
                )
            )
            + "."
        )

    if component_values.get("custom_status") not in [
        "Available",
        "Repaired"
    ]:
        frappe.throw(
            "Incoming Equipment Component "
            + str(incoming_component)
            + " has status "
            + str(component_values.get("custom_status"))
            + " and cannot be installed from stock."
        )


    # =========================
    # VALIDATE ERPNext SERIAL NO
    # =========================

    serial_values = frappe.db.get_value(
        "Serial No",
        serial_no,
        [
            "item_code",
            "warehouse"
        ],
        as_dict=True
    )

    if not serial_values:
        frappe.throw(
            "ERPNext Serial No was not found: "
            + str(serial_no)
        )

    if serial_values.get("item_code") != item_code:
        frappe.throw(
            "Serial No "
            + str(serial_no)
            + " belongs to Item "
            + str(
                serial_values.get("item_code") or ""
            )
            + ", not "
            + str(item_code)
            + "."
        )

    if serial_values.get("warehouse") != source_warehouse:
        frappe.throw(
            "Serial No "
            + str(serial_no)
            + " is no longer available in Warehouse "
            + str(source_warehouse)
            + "."
        )


# =========================
# WHOLE-EQUIPMENT MOVEMENT VALIDATION
# Skip this section for component replacement.
# =========================

classification = doc.get("custom_swap_classification")


if intervention_type == "Asset Relocation":

    if not classification:
        doc.custom_swap_classification = "Relocated"

    if not doc.get("custom_new_branch"):
        frappe.throw(
            "Destination Location is required for asset relocation."
        )

    if not doc.get("custom_asset_change_reason"):
        frappe.throw(
            "Change Reason is required for asset relocation."
        )


if (
    intervention_type == "Swap"
    and not component_replacement
    and not component_installation
):

    if not classification:
        doc.custom_swap_classification = "Permanent Swap"

    if not doc.get("custom_new_asset"):
        frappe.throw(
            "Replacement Equipment is required for equipment swap."
        )

    if not replacement_source:
        frappe.throw(
            "Replacement Source is required for equipment swap."
        )

    if not removed_asset_outcome:
        frappe.throw(
            "Removed Asset Outcome is required for equipment swap."
        )

    if not doc.get("custom_asset_change_reason"):
        frappe.throw(
            "Change Reason is required for equipment swap."
        )

    if (
        removed_asset_outcome == "Workshop for Repair"
        and not doc.get("custom_company_workshop")
    ):
        frappe.throw(
            "Company Workshop is required when the removed equipment "
            "is sent for repair."
        )

    if (
        removed_asset_outcome == "Installed at Another Site"
        and not doc.get("custom_new_branch")
    ):
        frappe.throw(
            "Destination Location is required when the removed equipment "
            "is installed at another site."
        )


if intervention_type == "Loan":

    if not classification:

        if str(
            doc.get("custom_loan_return") or "0"
        ) == "1":
            doc.custom_swap_classification = "Loan Returned"

        else:
            doc.custom_swap_classification = "Loan Issued"

    if (
        doc.get("custom_swap_classification")
        == "Loan Issued"
        and not doc.get("custom_new_asset")
    ):
        frappe.throw(
            "Loan Equipment is required for Loan Issued."
        )

    if not doc.get("custom_asset_change_reason"):
        frappe.throw(
            "Change Reason is required for loan."
        )


if (
    intervention_type == "Installation"
    and not component_installation
):

    if not classification:
        doc.custom_swap_classification = "Installed"

    if not doc.get("custom_new_branch"):
        frappe.throw(
            "Destination Location is required for installation."
        )


if intervention_type == "Commissioning":

    if not classification:
        doc.custom_swap_classification = "Commissioned"


if intervention_type == "Retirement":

    if not classification:
        doc.custom_swap_classification = "Retired"

    if not doc.get("custom_asset_change_reason"):
        frappe.throw(
            "Change Reason is required for retirement."
        )


if intervention_type == "Disposal":

    if not classification:
        doc.custom_swap_classification = "Disposed"

    if not doc.get("custom_asset_change_reason"):
        frappe.throw(
            "Change Reason is required for disposal."
        )

ticket_id = doc.custom_service_ticket
requires_parts = doc.custom_requires_parts or 0

if not ticket_id:
    for item in doc.items:
        if item.prevdoc_docname:
            vals = frappe.db.get_value(
                "Quotation",
                item.prevdoc_docname,
                ["custom_service_ticket", "custom_requires_parts"],
                as_dict=True
            )

            if vals:
                ticket_id = vals.custom_service_ticket
                requires_parts = vals.custom_requires_parts or 0
                break

if ticket_id:
    try:
        ticket = frappe.get_doc("Service Ticket", ticket_id)

        technical_status = ticket.get("custom_ticket_status") or ""
        work_done = technical_status in ["Resolved", "Closed"]

        ticket.custom_requires_parts = requires_parts

        if requires_parts:
            if work_done:
                # Preserve completed technical status
                ticket.custom_ticket_status = technical_status
                ticket.custom_hold_reason = ""
                ticket.custom_commercial_status = "To be Invoiced"
            else:
                ticket.custom_ticket_status = "On Hold"
                ticket.custom_hold_reason = "Awaiting Parts"
                ticket.custom_commercial_status = "Awaiting Parts"

        else:
            if work_done:
                # Preserve Resolved or Closed
                ticket.custom_ticket_status = technical_status
                ticket.custom_hold_reason = ""
                ticket.custom_commercial_status = "To be Invoiced"
            else:
                ticket.custom_ticket_status = "Ready for Planning"
                ticket.custom_hold_reason = ""
                ticket.custom_commercial_status = "Ready for Planning"

        exists = False

        for row in ticket.get("custom_commercial_references") or []:
            if (
                row.custom_reference_type == "Sales Order"
                and row.custom_reference_name == doc.name
            ):
                exists = True
                row.custom_status = doc.status
                row.custom_amount = doc.grand_total or 0
                row.custom_posting_date = doc.transaction_date
                row.custom_remarks = "Sales Order submitted"

        if not exists:
            ticket.append("custom_commercial_references", {
                "custom_reference_type": "Sales Order",
                "custom_reference_name": doc.name,
                "custom_status": doc.status,
                "custom_amount": doc.grand_total or 0,
                "custom_posting_date": doc.transaction_date,
                "custom_remarks": "Sales Order submitted"
            })

        ticket.save(ignore_permissions=True)

        if not doc.custom_service_ticket:
            frappe.db.set_value(
                "Sales Order",
                doc.name,
                "custom_service_ticket",
                ticket_id
            )

        if doc.custom_requires_parts != requires_parts:
            frappe.db.set_value(
                "Sales Order",
                doc.name,
                "custom_requires_parts",
                requires_parts
            )

    except Exception:
        frappe.log_error(
            frappe.get_traceback(),
            "Sales Order Service Ticket Sync Failed"
        )

ticket_id = doc.custom_service_ticket

if not ticket_id:
    for item in doc.items:
        if item.sales_order:
            ticket_id = frappe.db.get_value(
                "Sales Order",
                item.sales_order,
                "custom_service_ticket"
            )
            if ticket_id:
                break

if ticket_id:
    try:
        ticket = frappe.get_doc("Service Ticket", ticket_id)

        ticket.custom_ticket_status = "On Hold"
        ticket.custom_hold_reason = "Awaiting Parts"
        ticket.custom_commercial_status = "Awaiting Parts"
        ticket.custom_requires_parts = 1

        exists = False
        for row in ticket.get("custom_commercial_references") or []:
            if row.custom_reference_type == "Purchase Order" and row.custom_reference_name == doc.name:
                exists = True
                row.custom_status = doc.status
                row.custom_amount = doc.grand_total or 0
                row.custom_posting_date = doc.transaction_date
                row.custom_remarks = "Purchase Order submitted"

        if not exists:
            ticket.append("custom_commercial_references", {
                "custom_reference_type": "Purchase Order",
                "custom_reference_name": doc.name,
                "custom_status": doc.status,
                "custom_amount": doc.grand_total or 0,
                "custom_posting_date": doc.transaction_date,
                "custom_remarks": "Purchase Order submitted"
            })

        ticket.save(ignore_permissions=True)

        if not doc.custom_service_ticket:
            frappe.db.set_value("Purchase Order", doc.name, "custom_service_ticket", ticket_id)

    except Exception as e:
        frappe.log_error(str(e), "Purchase Order Service Ticket Sync Failed")

ticket_id = doc.custom_service_ticket

if not ticket_id:
    for item in doc.items:
        if item.purchase_order:
            ticket_id = frappe.db.get_value(
                "Purchase Order",
                item.purchase_order,
                "custom_service_ticket"
            )
            if ticket_id:
                break

if ticket_id:
    try:
        ticket = frappe.get_doc("Service Ticket", ticket_id)

        ticket.custom_ticket_status = "Ready for Planning"
        ticket.custom_hold_reason = ""
        ticket.custom_commercial_status = "Ready for Planning"
        ticket.custom_requires_parts = 1

        exists = False
        for row in ticket.get("custom_commercial_references") or []:
            if row.custom_reference_type == "Purchase Receipt" and row.custom_reference_name == doc.name:
                exists = True
                row.custom_status = doc.status
                row.custom_amount = doc.grand_total or 0
                row.custom_posting_date = doc.posting_date
                row.custom_remarks = "Purchase Receipt submitted"

        if not exists:
            ticket.append("custom_commercial_references", {
                "custom_reference_type": "Purchase Receipt",
                "custom_reference_name": doc.name,
                "custom_status": doc.status,
                "custom_amount": doc.grand_total or 0,
                "custom_posting_date": doc.posting_date,
                "custom_remarks": "Purchase Receipt submitted"
            })

        ticket.save(ignore_permissions=True)

        if not doc.custom_service_ticket:
            frappe.db.set_value("Purchase Receipt", doc.name, "custom_service_ticket", ticket_id)

    except Exception as e:
        frappe.log_error(str(e), "Purchase Receipt Service Ticket Sync Failed")

ticket_id = doc.custom_service_ticket

if not ticket_id:
    for item in doc.items:
        if item.against_sales_order:
            ticket_id = frappe.db.get_value(
                "Sales Order",
                item.against_sales_order,
                "custom_service_ticket"
            )
            if ticket_id:
                break

if ticket_id:
    try:
        ticket = frappe.get_doc("Service Ticket", ticket_id)

        if ticket.custom_ticket_status not in ["Resolved", "Closed"]:
            ticket.custom_ticket_status = "Ready for Planning"

        ticket.custom_hold_reason = ""

        if ticket.custom_commercial_status in ["Awaiting Parts", "Quote Approved"]:
            ticket.custom_commercial_status = "Ready for Planning"

        exists = False
        for row in ticket.get("custom_commercial_references") or []:
            if row.custom_reference_type == "Delivery Note" and row.custom_reference_name == doc.name:
                exists = True
                row.custom_status = doc.status
                row.custom_amount = doc.grand_total or 0
                row.custom_posting_date = doc.posting_date
                row.custom_remarks = "Delivery Note submitted"

        if not exists:
            ticket.append("custom_commercial_references", {
                "custom_reference_type": "Delivery Note",
                "custom_reference_name": doc.name,
                "custom_status": doc.status,
                "custom_amount": doc.grand_total or 0,
                "custom_posting_date": doc.posting_date,
                "custom_remarks": "Delivery Note submitted"
            })

        ticket.save(ignore_permissions=True)

        if not doc.custom_service_ticket:
            frappe.db.set_value("Delivery Note", doc.name, "custom_service_ticket", ticket_id)

    except Exception as e:
        frappe.log_error(str(e), "Delivery Note Service Ticket Sync Failed")

ticket_id = doc.custom_service_ticket

if not ticket_id:
    for item in doc.items:
        if item.sales_order:
            ticket_id = frappe.db.get_value(
                "Sales Order",
                item.sales_order,
                "custom_service_ticket"
            )
            if ticket_id:
                break

if ticket_id:
    try:
        ticket = frappe.get_doc("Service Ticket", ticket_id)

        ticket.custom_commercial_status = "Invoiced"

        exists = False
        for row in ticket.get("custom_commercial_references") or []:
            if row.custom_reference_type == "Sales Invoice" and row.custom_reference_name == doc.name:
                exists = True
                row.custom_status = doc.status
                row.custom_amount = doc.grand_total or 0
                row.custom_posting_date = doc.posting_date
                row.custom_remarks = "Sales Invoice submitted"

        if not exists:
            ticket.append("custom_commercial_references", {
                "custom_reference_type": "Sales Invoice",
                "custom_reference_name": doc.name,
                "custom_status": doc.status,
                "custom_amount": doc.grand_total or 0,
                "custom_posting_date": doc.posting_date,
                "custom_remarks": "Sales Invoice submitted"
            })

        ticket.save(ignore_permissions=True)

        if not doc.custom_service_ticket:
            frappe.db.set_value("Sales Invoice", doc.name, "custom_service_ticket", ticket_id)

    except Exception as e:
        frappe.log_error(str(e), "Sales Invoice Service Ticket Sync Failed")

for ref in doc.get("references") or []:

    if ref.reference_doctype != "Sales Invoice":
        continue

    if not ref.reference_name:
        continue

    ticket_id = frappe.db.get_value(
        "Sales Invoice",
        ref.reference_name,
        "custom_service_ticket"
    )

    if not ticket_id:
        continue

    if not frappe.db.exists("Service Ticket", ticket_id):
        continue

    outstanding = frappe.db.get_value(
        "Sales Invoice",
        ref.reference_name,
        "outstanding_amount"
    ) or 0

    ticket = frappe.get_doc("Service Ticket", ticket_id)

    if outstanding <= 0:
        ticket.custom_commercial_status = "Paid"
        payment_status = "Paid"
    else:
        ticket.custom_commercial_status = "Partly Paid"
        payment_status = "Partly Paid"

    exists = False

    for row in ticket.get("custom_commercial_references") or []:
        if (
            row.custom_reference_type == "Payment Entry"
            and row.custom_reference_name == doc.name
        ):
            exists = True
            row.custom_status = payment_status
            row.custom_amount = doc.paid_amount or 0
            row.custom_posting_date = doc.posting_date
            row.custom_remarks = "Payment Entry submitted"

    if not exists:
        ticket.append("custom_commercial_references", {
            "custom_reference_type": "Payment Entry",
            "custom_reference_name": doc.name,
            "custom_status": payment_status,
            "custom_amount": doc.paid_amount or 0,
            "custom_posting_date": doc.posting_date,
            "custom_remarks": "Payment Entry submitted"
        })

    ticket.save(ignore_permissions=True)

ticket_id = doc.get("custom_service_ticket")

if ticket_id and frappe.db.exists("Service Ticket", ticket_id):

    outstanding = doc.outstanding_amount or 0

    ticket = frappe.get_doc("Service Ticket", ticket_id)

    if outstanding <= 0 and doc.docstatus == 1:
        ticket.custom_commercial_status = "Paid"

    elif outstanding > 0 and doc.docstatus == 1:
        if doc.paid_amount and doc.paid_amount > 0:
            ticket.custom_commercial_status = "Partly Paid"
        else:
            ticket.custom_commercial_status = "Invoiced"

    ticket.save(ignore_permissions=True)

if (
    doc.custom_planned_starttime
    and doc.custom_planned_endtime
    and doc.custom_planned_starttime >= doc.custom_planned_endtime
):
    frappe.throw("Planned End Time must be after Planned Start Time.")

if (
    doc.get("custom_ticket_type") == "Incident Investigation"
    and doc.get("custom_ticket_status") == "Closed"
    and doc.get("custom_hse_incident_report")
):

    hse = frappe.get_doc(
        "HSE Incident Report",
        doc.get("custom_hse_incident_report")
    )

    if hse.get("custom_incident_status") != "Closed":

        hse.custom_incident_status = "Closed"

        if hse.meta.has_field("custom_investigation_summary"):
            hse.custom_investigation_summary = (
                doc.get("custom_resolution_details")
                or doc.get("custom_closure_notes")
                or doc.get("custom_description")
                or ""
            )

        if hse.meta.has_field("custom_closed_by"):
            hse.custom_closed_by = (
                frappe.db.get_value("User", frappe.session.user, "full_name")
                or frappe.session.user
            )

        if hse.meta.has_field("custom_closed_on"):
            hse.custom_closed_on = frappe.utils.now_datetime()

        hse.save(ignore_permissions=True)

# Server Script
# Reference DocType: Calibration Record
# Event: After Submit

if not doc.get("custom_mission_intervention"):
    frappe.throw("Mission Intervention is required on Calibration Record.")

mi = frappe.get_doc(
    "Mission Intervention",
    doc.custom_mission_intervention
)

# ------------------------------------------------------------------
# 1. Link the submitted Calibration Record back to the MI
# ------------------------------------------------------------------
if mi.meta.has_field("custom_calibration_record"):
    mi.custom_calibration_record = doc.name

# ------------------------------------------------------------------
# 2. Build a readable calibration summary for MI technical notes
# ------------------------------------------------------------------
summary_lines = [
    "Calibration completed.",
    "Calibration Record: " + str(doc.name)
]

if doc.get("custom_overall_result"):
    summary_lines.append(
        "Result: " + str(doc.custom_overall_result)
    )

if doc.get("custom_certificate_number"):
    summary_lines.append(
        "Certificate No.: " + str(doc.custom_certificate_number)
    )

if doc.get("custom_calibration_date"):
    summary_lines.append(
        "Calibration Date: " +
        str(frappe.utils.getdate(doc.custom_calibration_date))
    )

if doc.get("custom_next_calibration_date"):
    summary_lines.append(
        "Next Calibration Date: " +
        str(doc.custom_next_calibration_date)
    )

if doc.get("custom_reference_standard"):
    summary_lines.append(
        "Reference Standard: " +
        str(doc.custom_reference_standard)
    )

if doc.get("custom_findings"):
    summary_lines.append(
        "Findings: " +
        str(doc.custom_findings)
    )

if doc.get("custom_corrective_action"):
    summary_lines.append(
        "Corrective Action: " +
        str(doc.custom_corrective_action)
    )

if doc.get("custom_recommendations"):
    summary_lines.append(
        "Recommendations: " +
        str(doc.custom_recommendations)
    )

if doc.get("custom_client_notes"):
    summary_lines.append(
        "Customer Notes: " +
        str(doc.custom_client_notes)
    )

calibration_summary = "\n".join(summary_lines)

# Avoid inserting the same submitted calibration summary twice.
existing_notes = mi.get("custom_work_progress") or ""

if str(doc.name) not in existing_notes:
    if existing_notes:
        mi.custom_work_progress = (
            existing_notes.rstrip()
            + "\n\n"
            + calibration_summary
        )
    else:
        mi.custom_work_progress = calibration_summary

mi.save(ignore_permissions=True)

# ------------------------------------------------------------------
# 3. Update calibration dates on Equipment Component OR Installed Equipment
# ------------------------------------------------------------------
calibration_date = None

if doc.get("custom_calibration_date"):
    calibration_date = frappe.utils.getdate(
        doc.custom_calibration_date
    )

next_calibration_date = doc.get(
    "custom_next_calibration_date"
)

component_name = doc.get(
    "custom_equipment_component"
)

equipment_name = doc.get(
    "custom_installed_equipment"
)

# ------------------------------------------------------------------
# Component calibration
# ------------------------------------------------------------------
if component_name:
    component = frappe.get_doc(
        "Equipment Component",
        component_name
    )

    if component.meta.has_field(
        "custom_last_calibration_date"
    ):
        component.custom_last_calibration_date = (
            calibration_date
        )

    if component.meta.has_field(
        "custom_next_calibration_date"
    ):
        component.custom_next_calibration_date = (
            next_calibration_date
        )

    if component.meta.has_field(
        "custom_last_calibration_record"
    ):
        component.custom_last_calibration_record = (
            doc.name
        )

    component.save(ignore_permissions=True)

    # Prefer the equipment linked on Calibration Record.
    # Fall back to the component's current parent equipment.
    parent_equipment = (
        equipment_name
        or component.get("custom_parent_equipment")
    )

    if parent_equipment:
        equipment = frappe.get_doc(
            "Installed Equipment",
            parent_equipment
        )

        child_updated = False

        for row in (
            equipment.get(
                "custom_installed_components"
            ) or []
        ):
            if (
                row.get("custom_equipment_component")
                == component_name
            ):
                if row.meta.has_field(
                    "custom_next_calibration_date"
                ):
                    row.custom_next_calibration_date = (
                        next_calibration_date
                    )
                    child_updated = True

                break

        if child_updated:
            equipment.save(
                ignore_permissions=True
            )

# ------------------------------------------------------------------
# Whole equipment calibration
# ------------------------------------------------------------------
elif equipment_name:
    equipment = frappe.get_doc(
        "Installed Equipment",
        equipment_name
    )

    if equipment.meta.has_field(
        "custom_last_calibration_date"
    ):
        equipment.custom_last_calibration_date = (
            calibration_date
        )

    if equipment.meta.has_field(
        "custom_next_calibration_date"
    ):
        equipment.custom_next_calibration_date = (
            next_calibration_date
        )

    if equipment.meta.has_field(
        "custom_last_calibration_record"
    ):
        equipment.custom_last_calibration_record = (
            doc.name
        )

    equipment.save(ignore_permissions=True)

else:
    frappe.throw(
        "Calibration Record must be linked to "
        "Installed Equipment or Equipment Component."
    )

# Calibration Record - Before Submit

interval_confirmed = doc.get(
    "custom_calibration_interval_confirmed"
)

if not interval_confirmed:
    frappe.throw(
        "Please confirm the next calibration interval before submitting."
    )


interval_months = doc.get(
    "custom_calibration_interval_months"
)

if interval_months is None:
    interval_months = 0

interval_months = int(interval_months)


if interval_months < 0:
    frappe.throw(
        "Calibration Interval Months cannot be negative."
    )


calibration_date = doc.get(
    "custom_calibration_date"
)

if not calibration_date:
    frappe.throw(
        "Calibration Date is required."
    )


# 0 means calibration is performed on demand.
if interval_months == 0:
    doc.custom_next_calibration_date = None

else:
    doc.custom_next_calibration_date = (
        frappe.utils.add_months(
            calibration_date,
            interval_months
        )
    )
